-- LitVerse Community schema; run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,wallet_address text unique,username text not null default 'LitVerse Member',avatar_url text,bio text not null default '',created_at timestamptz not null default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,category text not null default 'General' check(category in ('General','NFT Showcase','Creator Zone','Marketplace','LitVM Ecosystem','Help')),content text not null default '' check(char_length(content)<=3000),image_path text,nft_name text,nft_url text,is_hidden boolean not null default false,created_at timestamptz not null default now(),constraint posts_content_or_media check(char_length(trim(content))>0 or image_path is not null or nft_url is not null));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,parent_id uuid references public.comments(id) on delete cascade,content text not null check(char_length(trim(content)) between 1 and 1200),created_at timestamptz not null default now());
create table if not exists public.post_likes(post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table if not exists public.follows(follower_id uuid not null references public.profiles(id) on delete cascade,following_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,reported_user_id uuid references public.profiles(id) on delete cascade,reason text not null check(char_length(trim(reason)) between 3 and 500),created_at timestamptz not null default now());
create table if not exists public.user_blocks(blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,kind text not null,message text not null default '',is_read boolean not null default false,created_at timestamptz not null default now());
create index if not exists posts_feed_idx on public.posts(created_at desc) where is_hidden=false;
create index if not exists comments_post_idx on public.comments(post_id,created_at);
create index if not exists notifications_user_idx on public.notifications(user_id,created_at desc);
alter table public.profiles enable row level security; alter table public.posts enable row level security; alter table public.comments enable row level security; alter table public.post_likes enable row level security; alter table public.follows enable row level security; alter table public.reports enable row level security; alter table public.user_blocks enable row level security; alter table public.notifications enable row level security;
drop policy if exists "profiles public read" on public.profiles; create policy "profiles public read" on public.profiles for select using(true);
drop policy if exists "profile owner insert" on public.profiles; create policy "profile owner insert" on public.profiles for insert to authenticated with check(id=auth.uid());
drop policy if exists "profile owner update" on public.profiles; create policy "profile owner update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists "posts visible read" on public.posts; create policy "posts visible read" on public.posts for select using(is_hidden=false);
drop policy if exists "wallet create posts" on public.posts; create policy "wallet create posts" on public.posts for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "post owner update" on public.posts; create policy "post owner update" on public.posts for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "post owner delete" on public.posts; create policy "post owner delete" on public.posts for delete to authenticated using(user_id=auth.uid());
drop policy if exists "comments public read" on public.comments; create policy "comments public read" on public.comments for select using(true);
drop policy if exists "wallet create comments" on public.comments; create policy "wallet create comments" on public.comments for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "comment owner delete" on public.comments; create policy "comment owner delete" on public.comments for delete to authenticated using(user_id=auth.uid());
drop policy if exists "likes public read" on public.post_likes; create policy "likes public read" on public.post_likes for select using(true);
drop policy if exists "wallet create likes" on public.post_likes; create policy "wallet create likes" on public.post_likes for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "like owner delete" on public.post_likes; create policy "like owner delete" on public.post_likes for delete to authenticated using(user_id=auth.uid());
drop policy if exists "follows public read" on public.follows; create policy "follows public read" on public.follows for select using(true);
drop policy if exists "wallet create follows" on public.follows; create policy "wallet create follows" on public.follows for insert to authenticated with check(follower_id=auth.uid());
drop policy if exists "follower delete follows" on public.follows; create policy "follower delete follows" on public.follows for delete to authenticated using(follower_id=auth.uid());
drop policy if exists "reporter create reports" on public.reports; create policy "reporter create reports" on public.reports for insert to authenticated with check(reporter_id=auth.uid());
drop policy if exists "block owner read" on public.user_blocks; create policy "block owner read" on public.user_blocks for select to authenticated using(blocker_id=auth.uid());
drop policy if exists "block owner insert" on public.user_blocks; create policy "block owner insert" on public.user_blocks for insert to authenticated with check(blocker_id=auth.uid());
drop policy if exists "block owner delete" on public.user_blocks; create policy "block owner delete" on public.user_blocks for delete to authenticated using(blocker_id=auth.uid());
drop policy if exists "notification owner read" on public.notifications; create policy "notification owner read" on public.notifications for select to authenticated using(user_id=auth.uid());
drop policy if exists "notification owner update" on public.notifications; create policy "notification owner update" on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('community-images','community-images',true,5242880,array['image/jpeg','image/png','image/gif','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/gif','image/webp'];
drop policy if exists "community image public read" on storage.objects; create policy "community image public read" on storage.objects for select using(bucket_id='community-images');
drop policy if exists "wallet upload community image" on storage.objects; create policy "wallet upload community image" on storage.objects for insert to authenticated with check(bucket_id='community-images' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "owner delete community image" on storage.objects; create policy "owner delete community image" on storage.objects for delete to authenticated using(bucket_id='community-images' and (storage.foldername(name))[1]=auth.uid()::text);
